# inspect test components and projections manually
R=C=16
unseen={(r,c) for r in range(R) for c in range(C) if test[r][c]!=7}
comps2=[]
while unseen:
 seed=unseen.pop();comp={seed};stack=[seed]
 while stack:
  r,c=stack.pop()
  for dr in (-1,0,1):
   for dc in (-1,0,1):
    q=(r+dr,c+dc)
    if q in unseen: unseen.remove(q);comp.add(q);stack.append(q)
 comps2.append(comp)
for comp in comps2:
 r0=min(r for r,c in comp);c0=min(c for r,c in comp)
 print(sorted(comp),sorted((r-r0,c-c0) for r,c in comp))
